from minitest import run_tests
def format_inr(amount):
    digits = str(amount)
    if len(digits) <= 3:
        return "₹" + digits
    head, tail = digits[:-3], digits[-3:]
    pairs = []
    while head:
        pairs.insert(0, head[-2:])
        head = head[:-2]
    return "₹" + ",".join(pairs) + "," + tail

def test_small():
    assert format_inr(500) == "₹500"

def test_thousands():
    assert format_inr(1500) == "₹1,500"

def test_lakhs():
    assert format_inr(123456) == "₹1,23,456"

def test_crores():
    assert format_inr(10000000) == "₹1,00,00,000"

run_tests(globals())

