def format_inr(amount: int) -> str:
    """Indian grouping: 1,23,456."""
    digits = str(amount)
    head, tail = digits[:-3], digits[-3:]
    groups = []
    while head:
        groups.insert(0, head[-2:])
        head = head[:-2]
    return "₹" + ",".join(groups + [tail])

